import{_ as t,c as o,o as n,ag as a}from"./chunks/framework.nnfp71k2.js";const p=JSON.parse('{"title":"BMFont Format: TXT vs XML","description":"The explanaton of the BMFont bitmap font format. The difference between the TXT and XML versions and which one to use.","frontmatter":{"description":"The explanaton of the BMFont bitmap font format. The difference between the TXT and XML versions and which one to use.","head":[["link",{"rel":"canonical","href":"https://calligro.ideasalmanac.com/tutorial/reference/bmfont-format"}],["meta",{"property":"og:url","content":"https://calligro.ideasalmanac.com/tutorial/reference/bmfont-format"}],["meta",{"property":"og:title","content":"BMFont Format: TXT vs XML | Calligro"}],["meta",{"property":"og:description","content":"The explanaton of the BMFont bitmap font format. The difference between the TXT and XML versions and which one to use."}],["meta",{"property":"twitter:title","content":"BMFont Format: TXT vs XML | Calligro"}],["meta",{"property":"twitter:description","content":"The explanaton of the BMFont bitmap font format. The difference between the TXT and XML versions and which one to use."}]]},"headers":[],"relativePath":"reference/bmfont-format.md","filePath":"reference/bmfont-format.md","lastUpdated":1790617747000}'),r={name:"reference/bmfont-format.md"};function i(s,e,l,c,f,m){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="bmfont-format-txt-vs-xml" tabindex="-1">BMFont Format: TXT vs XML <a class="header-anchor" href="#bmfont-format-txt-vs-xml" aria-label="Permalink to &quot;BMFont Format: TXT vs XML&quot;">​</a></h1><p>Calligro exports fonts in the BMFont format, created by AngelCode. It&#39;s the most widely supported bitmap font format in game engines and frameworks.</p><p>A BMFont font consists of:</p><ul><li>a <strong><code>.fnt</code> file</strong>: describes the font properties and where each character is on the image</li><li>one or more <strong><code>.png</code> pages</strong>: the images containing the characters</li></ul><p>The <code>.fnt</code> file refers to the pages by file name so keep them in the same folder.</p><h2 id="txt-vs-xml" tabindex="-1">TXT vs XML <a class="header-anchor" href="#txt-vs-xml" aria-label="Permalink to &quot;TXT vs XML&quot;">​</a></h2><p>The <code>.fnt</code> file comes in several versions with the same content in different syntax.</p><p>Calligro can export the two most common versions: TXT (<code>key=value</code> pairs) and XML . Both files use the <code>.fnt</code> extension. Engines usually support only one of them and it&#39;s generally undocumented. See the <a href="/tutorial/engines/#compatibility">compatibility table</a> for the known formats.</p><h2 id="kerning" tabindex="-1">Kerning <a class="header-anchor" href="#kerning" aria-label="Permalink to &quot;Kerning&quot;">​</a></h2><p>Kerning pairs are part of the BMFont specification but not all engines support them. See the <a href="/tutorial/engines/#compatibility">compatibility table</a> and <a href="/tutorial/guide/spacing-and-kerning#kerning-pairs">Spacing and Kerning</a>.</p><h2 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h2><ul><li><a href="https://www.angelcode.com/products/bmfont/doc/file_format.html" target="_blank" rel="noreferrer">Official BMFont file format documentation</a></li></ul>',12)])])}const d=t(r,[["render",i]]);export{p as __pageData,d as default};
